import React from "react";
import classes from './Products.module.css';

const Product_Items = [
    {
      id: "1",
      name: " Blue Jockey ",
      description: "80 % cotton 20 % polyster",
      price: 500.0,
    },
    {
      id: "2",
      name: " Neavy Blue Armani",
      description: "100 % cotton",
      price: 1299.0,
    },
    {
      id: "3",
      name: "Blue Gucci",
      description: "100 % cotton ",
      price: 1399.0,
    },
   
   
  ];

const Products=()=>{
    const clotheItems = Product_Items.map((item) => (
        <div key={item.id} className={classes.dish}>
          <div className={classes.category1} >{item.name}</div>
          <div className={classes.category2} >{item.description}</div>
          <div className={classes.category3}>Rs {item.price}</div>
          <div className={classes.form}>
            <ProductForm
                 meal={item}
                 ></ProductForm>
          </div>
        </div>
      ));
    
    return(
        <div>
        <ul>{clotheItems}</ul>
      </div>
    )
}
export default Products;
